INSERT INTO `units` (`id`, `name`, `created_at`) VALUES ('00000000-0000-0000-0000-000000000003', 'SUPPLIER_SETTINGS:{"bannerImageUrl":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/supplier_banner_1790581721988_4hnupy6deyk.jpeg","bannerTitle":"","bannerSubtitle":"","bannerBadge":"","bannerButtonText":"","bannerButtonLink":"","bannerOverlayOpacity":19,"bannerHeight":540,"bannerImageFit":"contain","sectionBadge":"","sectionTitle":"ASUS x GeForce RTX 50 Series Laptops","sectionDescription":"Selected ASUS laptops powered by NVIDIA GeForce RTX 50 Series graphics for study, creative work, gaming and more.","selectedProductIds":["029fe0b2-a35f-4da2-b20a-2dcbcfb35aa4","4fad44e0-61cb-4669-945f-c99739492e4d","e53f5516-a670-4dba-82e0-38ff10003293","c4b0da8e-5a03-494e-b582-85ed14e0e9e4","2a951f52-b544-4e66-88fb-4ea5ec24789c","b30d1841-e8df-437b-a544-9e18f2d96b57"]}', '2026-09-18T22:48:16.868554+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `units` (`id`, `name`, `created_at`) VALUES ('00000000-0000-0000-0000-000000000002', 'OUR_STORY_SETTINGS:{"id":"our_story","hero_eyebrow":"ABOUT MEADOW","hero_title":"Trusted in IT Retail & Distribution Since 1995.","hero_paragraph_1":"Meadow Computer is a computer retailer and distributor offering a wide range of PCs, laptops, components, printers and everyday IT products through our retail stores. Our journey began in distribution in 1995, before gradually expanding into retail with Meadow Computer stores, together with official ASUS and HP concept stores.","hero_paragraph_2":"Over the years, we have grown alongside the technology industry while building long-standing relationships with leading brands and the customers we serve.","hero_paragraph_3":"For us, the experience does not end when a product is sold. We want customers to feel confident about what they buy, with practical advice before their purchase and dependable after-sales support whenever they need it.\\n\\n\\n","hero_image_url":"https://images.unsplash.com/photo-1517430816045-df4b7de11d1d?auto=format&fit=crop&q=80","foundations_eyebrow":"Foundations","foundations_title":"We help every customer choose the right products with genuine advice and the right value for their needs.","foundations_feature1_title":"Official Brand Partnership","foundations_feature1_desc":"As one of the largest distributors in Johor, we work with leading brands across laptops, printers, monitors, PC components and everyday IT products, giving customers more choice from brands they trust in one place.","foundations_feature2_title":"Workshop Backed Support","foundations_feature2_desc":"Our in-store workshop supports customers with problem diagnosis, formatting, dust cleaning, warranty coordination and technical follow-up after purchase.","foundations_image_url":"https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&q=80","locations_eyebrow":"Distribution","locations_title":"Our Locations","locations_desc":"Across Meadow signature stores and official HP and ASUS concept stores, customers can browse, compare, and get practical advice in person. From laptops and printers to PC components and custom builds, our team is here to help you choose with greater clarity and confidence.","locations_btn_text":"Explore our locations","locations_btn_link":"/our-stores","locations_image_url":"https://images.unsplash.com/photo-1497366216548-37526070297c?auto=format&fit=crop&q=80","awards_section_title":"We\'re Multi-Award Company.","awards_section_desc":"We have been honored with awards from multiple international brands and local authorities, recognized for our nationwide distribution capabilities and our best-in-class products and services.","awards_tag_label":"Award List","award_cards":[{"id":"asus","type":"Computer Hardware Company","awards":["Millions Dollar Award","Top Contribution Award","Top Performance Partner Award"],"company":"ASUSTeK Computer Inc","duration":"Consecutively 2015-2023 Award Winner","logo_url":""},{"id":"msi","type":"Computer Hardware Company","awards":["Outstanding Award","Top Performance Award","Best Performance Award","Online Best Performance Award"],"company":"Micro-Star International Co. Ltd","duration":"Consecutively 2013-2024 Award Winner","logo_url":""},{"id":"gigabyte","type":"Computer Hardware & Components","awards":["Excellence in Retail Sales","Outstanding System Integrator Partner","Top Growth Partner Award"],"company":"Gigabyte Technology Co., Ltd.","duration":"Consecutively 2016-2024 Award Winner","logo_url":""},{"id":"hp","type":"Computing & Printing Technology","awards":["Best Retail Growth Award","Outstanding Concept Store Partner","Top Consumer PC Partner"],"company":"HP Inc. Malaysia","duration":"Consecutively 2016-2024 Award Winner","logo_url":""}],"commitment_eyebrow":"Our Commitment","commitment_quote":"\\"We serve those who define the future. To provide anything less than perfection would be to fail the vision of our clients.\\"","val1_title":"Integrity","val1_desc":"Honest consultation, transparent pricing, and genuine components from verified global supply chains.","val2_title":"Mastery","val2_desc":"Continuous research into emerging hardware architectures and thermal optimization techniques.","val3_title":"Support","val3_desc":"A lifecycle-long commitment to the machines we build, ensuring they evolve with your ambitions.","updated_at":"2026-09-23T14:34:14.644Z"}', '2026-08-11T05:46:40.547187+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `units` (`id`, `name`, `created_at`) VALUES ('00000000-0000-0000-0000-000000000001', 'HOMEPAGE_SETTINGS:{"id":"home","hero_bg_text":"Precision Engineering","hero_title":"Database Powered Title","hero_subtitle":"Explore high performance laptops, workstations, and custom PC components.","banners":[{"id":"banner-1789732553633","link":"/products","title":"","subtitle":"","image_url":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/home_1789732595487_6a94rh9k2su.jpg","is_active":true,"button_text":""},{"id":"banner-1","link":"https://google.com","title":"","subtitle":"","image_url":"https://hxfftpvzumcvtnzbpegb.supabase.co/storage/v1/object/public/generals/banner_1.png","is_active":true,"button_text":""},{"id":"banner-2","link":"/products?category=laptop","title":"","subtitle":"","image_url":"https://hxfftpvzumcvtnzbpegb.supabase.co/storage/v1/object/public/generals/banner_2.jpg","is_active":true,"button_text":""}],"categories":[{"id":"cat-1","name":"PC Component","slug":"pc-component","order":1,"image_url":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/home_1790016745465_ub6f7qg110t.png","is_active":true},{"id":"cat-2","name":"Laptop","slug":"laptop","order":2,"image_url":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/home_1790010758417_8pkriacpqx3.png","is_active":true},{"id":"cat-3","name":"Peripheral","slug":"peripheral","order":3,"image_url":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/home_1790011565499_8ls1fpynipv.jpg","is_active":true},{"id":"cat-4","name":"Monitor","slug":"monitor","order":4,"image_url":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/home_1790016283406_8zd69xh1xhm.png","is_active":true},{"id":"cat-5","name":"Desktop","slug":"desktop","order":5,"image_url":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/home_1790008973501_3sxxqaedn46.png","is_active":true},{"id":"cat-6","name":"Home & Office","slug":"home-office","order":6,"image_url":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/home_1790009078916_qboqj3yxwj8.jpg","is_active":true},{"id":"cat-8","name":"Smart Home","slug":"smart-home","order":8,"image_url":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/home_1790009481530_bzzbcpgkpk9.jpg","is_active":true}],"custom_pc_title":"Build Your Own PC.","custom_pc_subtitle":"Pick your parts step by step to build your dream PC that suits your budget and needs. Full warranty and after-sales support.","custom_pc_btn_text":"Coming SOON","custom_pc_btn_link":"/customised","custom_pc_bg_image":"https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/home_1790127320808_gr2p9vevhjd.png","store_section_title":"Visit Our Store.","store_card_title":"View All Meadow\\nComputer Mega Store\\nLocation.","store_btn_text":"Our Stores","store_btn_link":"/our-stores","store_video_label":"TAMAN PELANGI ASUS STORE","store_media_url":"https://illuminatelabs.space/assets/locator_vd.mp4","store_media_type":"video","updated_at":"2026-09-26T10:52:24.500Z"}', '2026-08-11T01:37:27.457857+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `category_id`, `subcategory_id`, `brand_id`, `unit_id`, `price`, `discount_type`, `discount_value`, `stock`, `image_url`, `description`, `additional_details`, `ddr_type`, `specs`, `is_custom_build`, `is_customised`, `is_Featured`, `is_Promo`, `created_at`) VALUES ('c7be7868-ad9f-4957-8c88-13b1a91568af', 'ASUS TUF FA506N-CGHN777WS Laptop | GeForce RTX3050 | AMD Ryzen 7 8845HS', 'asus-tuf-fa506n-cghn777ws-laptop--geforce-rtx3050--amd-ryzen-7-8845hs', 'c5e0f42f-1e3a-471c-975f-b0373e3c5767', '175c355e-88bb-4518-bd09-a5e23dda0be2', '558c6aff-e104-4e18-85bc-22db68f59926', '0399d064-885d-4ad2-b6e6-4f9d5a8c0ae7', 4099, 'fixed', 100, NULL, 'https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/product-images/s574vkv0w8a.webp', 'ASUS TUF Gaming A15 FA506N-CGHN777WS features an AMD Ryzen™ 7 8845HS processor, AMD XDNA™ AI NPU, NVIDIA® GeForce RTX™ 3050 4GB Laptop GPU, 15.6-inch Full HD 144Hz IPS-level display, 8GB DDR5 RAM, 512GB PCIe 4.0 SSD, Wi-Fi 6, Windows 11 Home, and MIL-STD 810H durability. Ideal for gaming, streaming, AI workloads, content creation, and everyday productivity.', 'The ASUS TUF Gaming A15 FA506N-CGHN777WS combines AMD Ryzen™ 7 AI performance, NVIDIA® GeForce RTX™ 3050 graphics, and a fast 144Hz display in a durable gaming laptop built for gaming, streaming, and creative workloads.\n\n\nAI-Enhanced Gaming Performance - AMD Ryzen™ 7 8845HS processor with AMD XDNA™ AI NPU and NVIDIA® GeForce RTX™ 3050 Laptop GPU deliver smooth gaming, AI-powered productivity, and reliable multitasking.\n\n\n15.6-inch FHD 144Hz Gaming Display\nFeatures 2 Description    15.6-inch Full HD IPS-level anti-glare display with a 144Hz refresh rate and Adaptive-Sync technology provides fluid gameplay and immersive visuals.\n\n\nUpgradeable DDR5 Memory & PCIe SSD - 8GB DDR5 RAM and a 512GB PCIe 4.0 NVMe SSD ensure responsive performance, while upgradeable memory and storage provide flexibility for future expansion.\n\n\nMilitary-Grade Durability & Complete Connectivity - Features MIL-STD 810H durability, USB-C, USB-A, HDMI, RJ45 LAN, Wi-Fi 6, Bluetooth®, DTS audio, backlit keyboard, Windows 11 Home, and Microsoft Office Home 2024.', '', '{"Color":"Black","Ports":"1x RJ45 LAN port; 1x USB 3.2 Gen 2 Type-C with support for DisplayPort™ (data speed up to 10Gbps); 3x USB 3.2 Gen 1 Type-A (data speed up to 5Gbps); 1x HDMI 2.1 TMDS; 1x 3.5mm Combo Audio Jack;","Memory":"8GB DDR5 SO-DIMM ( extra slot )","Battery":"48WHrs, 3S1P, 3-cell Li-ion","Display":"15.6-inch, FHD (1920 x 1080) 16:9, IPS-level, Anti-glare display, 144Hz","Storage":"512GB PCIe® 4.0 NVMe™ M.2 SSD ( extra slot )","Graphics":"NVIDIA® GeForce RTX™ 3050 Laptop GPU 4GB GDDR6","Keyboard":"Backlit Chiclet Keyboard 1-Zone RGB","Security":"N/A","Wireless":"Wi-Fi 6(802.11ax) (Dual band) 2*2 + Bluetooth® 5.3 Wireless Card (*Bluetooth® version may change with OS version different.)","ddr_type":"","Processor":"AMD Ryzen™ 7 8845HS Mobile Processor","Web Camera":"720P HD camera","Total Weight":"2.30 Kg","Included Items":"Backpack","Operating System":"Windows 11 Home","Included Software":"N/A","additional_details":"The ASUS TUF Gaming A15 FA506N-CGHN777WS combines AMD Ryzen™ 7 AI performance, NVIDIA® GeForce RTX™ 3050 graphics, and a fast 144Hz display in a durable gaming laptop built for gaming, streaming, and creative workloads.\\n\\n\\nAI-Enhanced Gaming Performance - AMD Ryzen™ 7 8845HS processor with AMD XDNA™ AI NPU and NVIDIA® GeForce RTX™ 3050 Laptop GPU deliver smooth gaming, AI-powered productivity, and reliable multitasking.\\n\\n\\n15.6-inch FHD 144Hz Gaming Display\\nFeatures 2 Description    15.6-inch Full HD IPS-level anti-glare display with a 144Hz refresh rate and Adaptive-Sync technology provides fluid gameplay and immersive visuals.\\n\\n\\nUpgradeable DDR5 Memory & PCIe SSD - 8GB DDR5 RAM and a 512GB PCIe 4.0 NVMe SSD ensure responsive performance, while upgradeable memory and storage provide flexibility for future expansion.\\n\\n\\nMilitary-Grade Durability & Complete Connectivity - Features MIL-STD 810H durability, USB-C, USB-A, HDMI, RJ45 LAN, Wi-Fi 6, Bluetooth®, DTS audio, backlit keyboard, Windows 11 Home, and Microsoft Office Home 2024."}', 0, 0, 0, 0, '2026-09-20T15:10:23.460135+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `category_id`, `subcategory_id`, `brand_id`, `unit_id`, `price`, `discount_type`, `discount_value`, `stock`, `image_url`, `description`, `additional_details`, `ddr_type`, `specs`, `is_custom_build`, `is_customised`, `is_Featured`, `is_Promo`, `created_at`) VALUES ('f61c3b59-24a7-4770-a22c-54dd45464ab0', 'ASUS TUF F16 FX607V-URL009W Laptop | GeForce RTX4050 | Intel Core 5 210H', 'asus-tuf-f16-fx607v-url009w-laptop--geforce-rtx4050--intel-core-5-210h', 'c5e0f42f-1e3a-471c-975f-b0373e3c5767', '175c355e-88bb-4518-bd09-a5e23dda0be2', '558c6aff-e104-4e18-85bc-22db68f59926', '0399d064-885d-4ad2-b6e6-4f9d5a8c0ae7', 4599, 'none', 0, 2, 'https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/product-images/isrjtn4z4m.webp', 'ASUS TUF Gaming F16 FX607V-URL009W features an Intel® Core™ 5 210H processor, NVIDIA® GeForce RTX™ 4050 6GB Laptop GPU, 16GB DDR5 RAM, 512GB PCIe® 4.0 NVMe™ SSD, and a 16-inch FHD+ 144Hz display. Built for gaming, multitasking, and demanding everyday workloads with Windows 11 Home.', 'Intel® Core™ Performance — Intel® Core™ 5 210H processor delivers strong performance for gaming, productivity, and multitasking.\n\nGeForce RTX™ 4050 Graphics — NVIDIA® GeForce RTX™ 4050 Laptop GPU with 6GB GDDR6 dedicated graphics for modern gaming and creative workloads.\n\n16-inch FHD+ 144Hz Gaming Display — 1920 × 1200 16:10 IPS-level anti-glare display with a fast 144Hz refresh rate.\n\nMUX Switch & Advanced Optimus — MUX Switch and NVIDIA® Advanced Optimus help optimize graphics performance and power efficiency.\n\nDDR5 Memory & Fast PCIe Storage — 16GB DDR5 memory and a 512GB PCIe® 4.0 NVMe™ M.2 SSD provide responsive performance and fast storage access.\n\nTUF-Grade Durability — MIL-STD-810H-tested construction with a Mecha Gray finish, Windows 11 Home, and ASUS gaming features.', '', '{"Color":"Mecha Gray","Ports":"1x Thunderbolt™ 4 with DisplayPort™; 1x USB 3.2 Gen 2 Type-C with DisplayPort™ / Power Delivery / G-SYNC; 2x USB 3.2 Gen 1 Type-A; 1x HDMI 2.1 FRL; 1x RJ45 LAN; 1x 3.5mm Combo Audio Jack","Memory":"16GB DDR5-5200 SO-DIMM (1×16GB, Extra Slot, Max 64GB)","Battery":"56WHrs, 4S1P, 4-cell Li-ion; 240W AC Adapter","Display":"16-inch FHD+ (1920 × 1200) 16:10, IPS-level, Anti-glare, 144Hz, G-SYNC, MUX Switch + NVIDIA® Advanced Optimus","Storage":"512GB PCIe® 4.0 NVMe™ M.2 SSD (Extra M.2 Slot)","Graphics":"NVIDIA® GeForce RTX™ 4050 Laptop GPU 6GB GDDR6","Keyboard":"Backlit Chiclet Keyboard, 1-Zone RGB","Security":"Firmware TPM, Kensington Security Slot™, BIOS Administrator & User Password Protection","Wireless":"Wi-Fi 6 (802.11ax) Dual Band 2×2 + Bluetooth® 5.3","ddr_type":"","Processor":"Intel® Core™ 5 210H Processor, 2.2GHz, 12MB Cache, up to 4.8GHz, 8 Cores / 12 Threads","Web Camera":"720P HD Camera","Total Weight":"2.20 kg","Included Items":"TUF Backpack, 240W AC Adapter","Operating System":"Windows 11 Home","Included Software":"N/A","additional_details":"Intel® Core™ Performance — Intel® Core™ 5 210H processor delivers strong performance for gaming, productivity, and multitasking.\\n\\nGeForce RTX™ 4050 Graphics — NVIDIA® GeForce RTX™ 4050 Laptop GPU with 6GB GDDR6 dedicated graphics for modern gaming and creative workloads.\\n\\n16-inch FHD+ 144Hz Gaming Display — 1920 × 1200 16:10 IPS-level anti-glare display with a fast 144Hz refresh rate.\\n\\nMUX Switch & Advanced Optimus — MUX Switch and NVIDIA® Advanced Optimus help optimize graphics performance and power efficiency.\\n\\nDDR5 Memory & Fast PCIe Storage — 16GB DDR5 memory and a 512GB PCIe® 4.0 NVMe™ M.2 SSD provide responsive performance and fast storage access.\\n\\nTUF-Grade Durability — MIL-STD-810H-tested construction with a Mecha Gray finish, Windows 11 Home, and ASUS gaming features."}', 0, 0, 0, 0, '2026-09-20T21:29:15.375736+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
