INSERT INTO `products` (`id`, `name`, `slug`, `category_id`, `subcategory_id`, `brand_id`, `unit_id`, `price`, `discount_type`, `discount_value`, `stock`, `image_url`, `description`, `additional_details`, `ddr_type`, `specs`, `is_custom_build`, `is_customised`, `is_Featured`, `is_Promo`, `created_at`) VALUES ('12b52d5f-c651-4f14-9143-b253650bcd54', 'ASUS TUF FA506N-CGHN566WSP Laptop | GeForce RTX3050 | AMD Ryzen 7 8845HS', 'asus-tuf-fa506n-cghn566wsp-laptop--geforce-rtx3050--amd-ryzen-7-8845hs', 'c5e0f42f-1e3a-471c-975f-b0373e3c5767', '175c355e-88bb-4518-bd09-a5e23dda0be2', '558c6aff-e104-4e18-85bc-22db68f59926', '0399d064-885d-4ad2-b6e6-4f9d5a8c0ae7', 4499, 'fixed', 200, 2, 'https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/product-images/fxte6m7uko.webp', 'ASUS TUF Gaming A15 FA506N-CGHN566WSP features an AMD Ryzen™ 7 8845HS processor, AMD XDNA™ AI NPU, NVIDIA® GeForce RTX™ 3050 4GB Laptop GPU, 15.6-inch FHD 144Hz IPS-level display, 16GB DDR5 RAM, 512GB PCIe 4.0 SSD, Wi-Fi 6, Windows 11 Home, and MIL-STD 810H durability. Perfect for gaming, streaming, content creation, AI workloads, and everyday productivity.', 'The ASUS TUF Gaming A15 FA506N-CGHN566WSP combines AMD Ryzen™ 7 AI performance, NVIDIA® GeForce RTX™ 3050 graphics, and a fast 144Hz display in a durable gaming laptop designed for gaming, streaming, and creative workloads.\n\n\nAI-Enhanced Gaming Performance - AMD Ryzen™ 7 8845HS processor with AMD XDNA™ AI NPU and NVIDIA® GeForce RTX™ 3050 Laptop GPU deliver smooth gaming, AI-enhanced productivity, and reliable multitasking.\n\n\n15.6-inch FHD 144Hz Gaming Display - 15.6-inch Full HD IPS-level anti-glare display with a 144Hz refresh rate and Adaptive-Sync technology provides fluid gameplay and immersive visuals.\n\n\nFast DDR5 Memory & Expandable Storage - 16GB DDR5 RAM and a 512GB PCIe 4.0 NVMe SSD ensure responsive performance, while additional RAM and SSD slots allow easy future upgrades.\n\n\nMilitary-Grade Durability & Comprehensive Connectivity - Features MIL-STD 810H durability, USB-C, USB-A, HDMI, RJ45 LAN, Wi-Fi 6, Bluetooth®, DTS audio, backlit keyboard, Windows 11 Home, and Microsoft Office Home 2024.\n\n ', '', '{"Color":"Black","Ports":"1x RJ45 LAN port; 1x USB 3.2 Gen 2 Type-C with support for DisplayPort™ (data speed up to 10Gbps); 3x USB 3.2 Gen 1 Type-A (data speed up to 5Gbps); 1x HDMI 2.1 TMDS; 1x 3.5mm Combo Audio Jack;","Memory":"16GB DDR5 SO-DIMM ( extra slot )","Battery":"48WHrs, 3S1P, 3-cell Li-ion","Display":"15.6-inch, FHD (1920 x 1080) 16:9, IPS-level, Anti-glare display, 144Hz","Storage":"512GB PCIe® 4.0 NVMe™ M.2 SSD ( extra slot )","Graphics":"NVIDIA® GeForce RTX™ 3050 Laptop GPU 4GB GDDR6","Keyboard":"Backlit Chiclet Keyboard 1-Zone RGB","Security":"N/A","Wireless":"Wi-Fi 6(802.11ax) (Dual band) 2*2 + Bluetooth® 5.3 Wireless Card (*Bluetooth® version may change with OS version different.)","ddr_type":"","Processor":"AMD Ryzen™ 7 8845HS Mobile Processor","Web Camera":"720P HD camera","Total Weight":"2.30 Kg","Included Items":"Backpack","Operating System":"Windows 11 Home","Included Software":"N/A","additional_details":"The ASUS TUF Gaming A15 FA506N-CGHN566WSP combines AMD Ryzen™ 7 AI performance, NVIDIA® GeForce RTX™ 3050 graphics, and a fast 144Hz display in a durable gaming laptop designed for gaming, streaming, and creative workloads.\\n\\n\\nAI-Enhanced Gaming Performance - AMD Ryzen™ 7 8845HS processor with AMD XDNA™ AI NPU and NVIDIA® GeForce RTX™ 3050 Laptop GPU deliver smooth gaming, AI-enhanced productivity, and reliable multitasking.\\n\\n\\n15.6-inch FHD 144Hz Gaming Display - 15.6-inch Full HD IPS-level anti-glare display with a 144Hz refresh rate and Adaptive-Sync technology provides fluid gameplay and immersive visuals.\\n\\n\\nFast DDR5 Memory & Expandable Storage - 16GB DDR5 RAM and a 512GB PCIe 4.0 NVMe SSD ensure responsive performance, while additional RAM and SSD slots allow easy future upgrades.\\n\\n\\nMilitary-Grade Durability & Comprehensive Connectivity - Features MIL-STD 810H durability, USB-C, USB-A, HDMI, RJ45 LAN, Wi-Fi 6, Bluetooth®, DTS audio, backlit keyboard, Windows 11 Home, and Microsoft Office Home 2024.\\n\\n "}', 0, 0, 0, 0, '2026-09-20T15:17:56.047056+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
