INSERT INTO `products` (`id`, `name`, `slug`, `category_id`, `subcategory_id`, `brand_id`, `unit_id`, `price`, `discount_type`, `discount_value`, `stock`, `image_url`, `description`, `additional_details`, `ddr_type`, `specs`, `is_custom_build`, `is_customised`, `is_Featured`, `is_Promo`, `created_at`) VALUES ('330b570d-8ccb-4ab4-bcb3-c1b8d91321b8', 'ASUS TUF FA506N-CQHN666WS Laptop | GeForce RTX3050 | AMD Ryzen 7 170', 'asus-tuf-fa506n-cqhn666ws-laptop--geforce-rtx3050--amd-ryzen-7-170', 'c5e0f42f-1e3a-471c-975f-b0373e3c5767', '175c355e-88bb-4518-bd09-a5e23dda0be2', '558c6aff-e104-4e18-85bc-22db68f59926', '0399d064-885d-4ad2-b6e6-4f9d5a8c0ae7', 5129, 'fixed', 4256.01, 2, 'https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/product-images/70af4q6qxtv.webp', 'ASUS TUF Gaming A15 FA506N-CQHN666WS features an AMD Ryzen™ 7 170 processor, NVIDIA® GeForce RTX™ 3050 4GB Laptop GPU, 15.6-inch Full HD 144Hz IPS-level display, 16GB DDR5 RAM, 512GB PCIe 4.0 NVMe SSD, Wi-Fi 6, Windows 11 Home, and Microsoft Office Home 2024. Built for gaming, multitasking, entertainment, and everyday productivity.', 'Ryzen™ 7 Gaming Performance — AMD Ryzen™ 7 170 processor with 8 cores and 16 threads delivers strong performance for gaming, multitasking, and everyday productivity.\n\nGeForce RTX™ 3050 Graphics — NVIDIA® GeForce RTX™ 3050 Laptop GPU with 4GB GDDR6 graphics for gaming, creative applications, and GPU-accelerated workloads.\n\n15.6-inch FHD 144Hz Display — Full HD IPS-level anti-glare display with a 144Hz refresh rate and Adaptive-Sync for smoother gameplay and visuals.\n\n16GB DDR5 Memory & 512GB PCIe SSD — Equipped with 16GB DDR5-4800 RAM and a 512GB PCIe® 4.0 NVMe™ SSD for fast system response and everyday performance.\n\nUpgradeable Memory & Storage — Supports RAM and storage expansion for future upgrades.\n\nComprehensive Connectivity — USB-C, USB-A, HDMI, RJ45 LAN, Wi-Fi 6, Bluetooth®, and 3.5mm audio connectivity.\n\nGaming Essentials — 1-zone RGB backlit keyboard, Windows 11 Home, and Microsoft Office Home 2024.\n', '', '{"Color":"Graphite Black","Ports":"1x RJ45 LAN port; 1x USB 3.2 Gen 2 Type-C with DisplayPort™ support (up to 10Gbps); 3x USB 3.2 Gen 1 Type-A (up to 5Gbps); 1x HDMI 2.1 TMDS; 1x 3.5mm Combo Audio Jack","Memory":"16GB DDR5-4800 SO-DIMM (Extra Slot, Max 64GB)","Battery":"48WHrs, 3S1P, 3-cell Li-ion","Display":"15.6-inch FHD (1920 × 1080) 16:9, IPS-level, Anti-glare Display, 144Hz, Adaptive-Sync","Storage":"512GB PCIe® 4.0 NVMe™ M.2 SSD (Extra M.2 Slot)","Graphics":"NVIDIA® GeForce RTX™ 3050 Laptop GPU 4GB GDDR6","Keyboard":"Backlit Chiclet Keyboard, 1-Zone RGB","Security":"N/A","Wireless":"Wi-Fi 6 (802.11ax) Dual Band 2×2 + Bluetooth® 5.3","ddr_type":"","Processor":"AMD Ryzen™ 7 170 Processor, 8 Cores / 16 Threads, up to 4.75 GHz","Web Camera":"720P HD Camera","Total Weight":"2.30 kg","Included Items":"ASUS Backpack","Operating System":"Windows 11 Home","Included Software":"Microsoft Office Home 2024 + Microsoft 365 Basic","additional_details":"Ryzen™ 7 Gaming Performance — AMD Ryzen™ 7 170 processor with 8 cores and 16 threads delivers strong performance for gaming, multitasking, and everyday productivity.\\n\\nGeForce RTX™ 3050 Graphics — NVIDIA® GeForce RTX™ 3050 Laptop GPU with 4GB GDDR6 graphics for gaming, creative applications, and GPU-accelerated workloads.\\n\\n15.6-inch FHD 144Hz Display — Full HD IPS-level anti-glare display with a 144Hz refresh rate and Adaptive-Sync for smoother gameplay and visuals.\\n\\n16GB DDR5 Memory & 512GB PCIe SSD — Equipped with 16GB DDR5-4800 RAM and a 512GB PCIe® 4.0 NVMe™ SSD for fast system response and everyday performance.\\n\\nUpgradeable Memory & Storage — Supports RAM and storage expansion for future upgrades.\\n\\nComprehensive Connectivity — USB-C, USB-A, HDMI, RJ45 LAN, Wi-Fi 6, Bluetooth®, and 3.5mm audio connectivity.\\n\\nGaming Essentials — 1-zone RGB backlit keyboard, Windows 11 Home, and Microsoft Office Home 2024.\\n"}', 0, 0, 0, 0, '2026-09-20T21:03:56.015386+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
