INSERT INTO `products` (`id`, `name`, `slug`, `category_id`, `subcategory_id`, `brand_id`, `unit_id`, `price`, `discount_type`, `discount_value`, `stock`, `image_url`, `description`, `additional_details`, `ddr_type`, `specs`, `is_custom_build`, `is_customised`, `is_Featured`, `is_Promo`, `created_at`) VALUES ('4c00d7cf-e5a0-40cd-8395-4c0f6eab149a', 'ASUS TUF A16 FA607N-UQRL788WS Laptop | GeForce RTX4050 | AMD Ryzen 7 170', 'asus-tuf-a16-fa607n-uqrl788ws-laptop--geforce-rtx4050--amd-ryzen-7-170', 'c5e0f42f-1e3a-471c-975f-b0373e3c5767', '175c355e-88bb-4518-bd09-a5e23dda0be2', '558c6aff-e104-4e18-85bc-22db68f59926', '0399d064-885d-4ad2-b6e6-4f9d5a8c0ae7', 4899, 'none', 0, 4, 'https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/product-images/fuohyh9khnw.webp', 'ASUS TUF Gaming A16 FA607N-UQRL788WS features an AMD Ryzen™ 7 170 processor, NVIDIA® GeForce RTX™ 4050 6GB Laptop GPU, 16-inch FHD+ 144Hz display, 8GB DDR5 RAM, and 512GB PCIe® 4.0 NVMe™ SSD. Built for gaming, multitasking, content creation, and everyday productivity, with Windows 11 Home and Microsoft Office Home 2024 included.\n', 'Ryzen™ 7 Gaming Performance — AMD Ryzen™ 7 170 processor with 8 cores and 16 threads for gaming, multitasking, and creative workloads.\n\nGeForce RTX™ 4050 Graphics — NVIDIA® GeForce RTX™ 4050 Laptop GPU with 6GB GDDR6 graphics and support for modern RTX technologies.\n\n16-inch FHD+ 144Hz Gaming Display — 1920 × 1200 16:10 IPS-level anti-glare display with 144Hz refresh rate, G-SYNC, MUX Switch, and NVIDIA® Advanced Optimus.\n\nDDR5 Memory & PCIe 4.0 Storage — 8GB DDR5 RAM paired with a 512GB PCIe® 4.0 NVMe™ M.2 SSD for responsive everyday performance.\n\nComplete Gaming Essentials — Wi-Fi 6, Bluetooth® 5.3, 1-zone RGB keyboard, Windows 11 Home, Microsoft Office Home 2024 + Microsoft 365 Basic, and ASUS backpack.', '', '{"Color":"Black","Ports":"1 x 3.5mm Combo Audio Jack; 1 x HDMI 2.1 FRL; 1 x RJ45 LAN port; 1 x Type-C USB 4 with support for DisplayPort™ / power delivery (data speed up to 40Gbps); 1 x USB 3.2 Gen 2 Type-C with support for DisplayPort™ / power delivery / G-SYNC (data speed up to 10Gbps); 2 x USB 3.2 Gen 1 Type-A (data speed up to 5Gbps);","Memory":"8GB DDR5 SO-DIMM","Battery":"56WHrs, 4S1P, 4-cell Li-ion","Display":"16-inch, FHD+ (1920 x 1200, WUXGA) 16:10 aspect ratio, Value IPS-level, Anti-glare display, NTSC:45%, Adobe:75.35%, Refresh Rate:144Hz, G-Sync,","Storage":"512GB PCIe® 4.0 NVMe™ M.2 SSD","Graphics":"NVIDIA® GeForce RTX™ 4050 Laptop GPU (194 AI TOPs), 6GB GDDR6","Keyboard":"Backlit Chiclet Keyboard 1-Zone RGB Touchpad With Copilot key","Security":"N/A","Wireless":"Wi-Fi 6(802.11ax) (Dual band) 2*2 + Bluetooth® 5.3 Wireless Car","ddr_type":"","Processor":"AMD Ryzen™ 7 170 Processor","Web Camera":"720P HD camera","Total Weight":"2.20 Kg","Included Items":"Backpack","Operating System":"Windows 11 Home","Included Software":"Preinstalled MS Office Home 2024 + Microsoft 365 Basic","additional_details":"Ryzen™ 7 Gaming Performance — AMD Ryzen™ 7 170 processor with 8 cores and 16 threads for gaming, multitasking, and creative workloads.\\n\\nGeForce RTX™ 4050 Graphics — NVIDIA® GeForce RTX™ 4050 Laptop GPU with 6GB GDDR6 graphics and support for modern RTX technologies.\\n\\n16-inch FHD+ 144Hz Gaming Display — 1920 × 1200 16:10 IPS-level anti-glare display with 144Hz refresh rate, G-SYNC, MUX Switch, and NVIDIA® Advanced Optimus.\\n\\nDDR5 Memory & PCIe 4.0 Storage — 8GB DDR5 RAM paired with a 512GB PCIe® 4.0 NVMe™ M.2 SSD for responsive everyday performance.\\n\\nComplete Gaming Essentials — Wi-Fi 6, Bluetooth® 5.3, 1-zone RGB keyboard, Windows 11 Home, Microsoft Office Home 2024 + Microsoft 365 Basic, and ASUS backpack."}', 0, 0, 0, 0, '2026-09-20T21:16:20.60631+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
INSERT INTO `products` (`id`, `name`, `slug`, `category_id`, `subcategory_id`, `brand_id`, `unit_id`, `price`, `discount_type`, `discount_value`, `stock`, `image_url`, `description`, `additional_details`, `ddr_type`, `specs`, `is_custom_build`, `is_customised`, `is_Featured`, `is_Promo`, `created_at`) VALUES ('086ced47-324c-464e-bcc4-65af80c95ee5', 'ASUS TUF A16 FA607N-UQRL888WS Laptop | GeForce RTX4050 | AMD Ryzen 7 170', 'asus-tuf-a16-fa607n-uqrl888ws-laptop--geforce-rtx4050--amd-ryzen-7-170', 'c5e0f42f-1e3a-471c-975f-b0373e3c5767', '175c355e-88bb-4518-bd09-a5e23dda0be2', '558c6aff-e104-4e18-85bc-22db68f59926', '0399d064-885d-4ad2-b6e6-4f9d5a8c0ae7', 5299, 'none', 0, 1, 'https://ecscjefihrntuhumtqwe.supabase.co/storage/v1/object/public/products/product-images/hd5zeextds5.webp', 'ASUS TUF Gaming A16 FA607N-UQRL888WS combines an AMD Ryzen™ 7 170 processor with NVIDIA® GeForce RTX™ 4050 6GB graphics, 16GB DDR5 RAM, a 512GB PCIe® 4.0 NVMe™ SSD, and a 16-inch FHD+ 144Hz gaming display. Designed for smooth gaming, multitasking, content creation, and everyday productivity.', 'Ryzen™ 7 Gaming Performance — AMD Ryzen™ 7 170 processor with 8 cores, 16 threads, and boost speeds up to 4.75GHz.\n\nGeForce RTX™ 4050 Graphics — NVIDIA® GeForce RTX™ 4050 Laptop GPU with 6GB GDDR6 dedicated graphics for gaming and GPU-accelerated workloads.\n\n16-inch FHD+ 144Hz Gaming Display — 1920 × 1200 16:10 IPS-level anti-glare display with 144Hz refresh rate, G-SYNC, MUX Switch, and NVIDIA® Advanced Optimus.\n\n16GB DDR5 & Expandable Storage — 16GB DDR5 memory and 512GB PCIe® 4.0 NVMe™ SSD, with dual SO-DIMM and dual M.2 expansion capability.\n\nComplete Gaming Connectivity — Wi-Fi 6, Bluetooth® 5.3, USB-C, HDMI 2.1, RJ45 LAN, 1-zone RGB keyboard, Windows 11 Home, and Microsoft Office Home 2024 + Microsoft 365 Basic.', '', '{"Color":"Black","Ports":"1 x 3.5mm Combo Audio Jack; 1 x HDMI 2.1 FRL; 1 x RJ45 LAN port; 1 x Type-C USB 4 with support for DisplayPort™ / power delivery (data speed up to 40Gbps); 1 x USB 3.2 Gen 2 Type-C with support for DisplayPort™ / power delivery / G-SYNC (data speed up to 10Gbps); 2 x USB 3.2 Gen 1 Type-A (data speed up to 5Gbps);","Memory":"16GB DDR5-5600 SO-DIMM","Battery":"56WHrs, 4S1P, 4-cell Li-ion","Display":"16-inch, FHD+ (1920 x 1200, WUXGA) 16:10 aspect ratio, Value IPS-level, Anti-glare display, NTSC:45%, Adobe:75.35%, Refresh Rate:144Hz, G-Sync,","Storage":"512GB PCIe® 4.0 NVMe™ M.2 SSD","Graphics":"NVIDIA® GeForce RTX™ 4050 Laptop GPU (194 AI TOPs), 6GB GDDR6","Keyboard":"Backlit Chiclet Keyboard 1-Zone RGB Touchpad With Copilot key","Security":"N/A","Wireless":"Wi-Fi 6(802.11ax) (Dual band) 2*2 + Bluetooth® 5.3 Wireless Card","ddr_type":"","Processor":"AMD Ryzen™ 7 170 Processor","Web Camera":"720P HD camera","Total Weight":"2.20 Kg","Included Items":"Backpack","Operating System":"Windows 11 Home","Included Software":"Preinstalled MS Office Home 2024 + Microsoft 365 Basic","additional_details":"Ryzen™ 7 Gaming Performance — AMD Ryzen™ 7 170 processor with 8 cores, 16 threads, and boost speeds up to 4.75GHz.\\n\\nGeForce RTX™ 4050 Graphics — NVIDIA® GeForce RTX™ 4050 Laptop GPU with 6GB GDDR6 dedicated graphics for gaming and GPU-accelerated workloads.\\n\\n16-inch FHD+ 144Hz Gaming Display — 1920 × 1200 16:10 IPS-level anti-glare display with 144Hz refresh rate, G-SYNC, MUX Switch, and NVIDIA® Advanced Optimus.\\n\\n16GB DDR5 & Expandable Storage — 16GB DDR5 memory and 512GB PCIe® 4.0 NVMe™ SSD, with dual SO-DIMM and dual M.2 expansion capability.\\n\\nComplete Gaming Connectivity — Wi-Fi 6, Bluetooth® 5.3, USB-C, HDMI 2.1, RJ45 LAN, 1-zone RGB keyboard, Windows 11 Home, and Microsoft Office Home 2024 + Microsoft 365 Basic."}', 0, 0, 0, 0, '2026-09-20T21:19:30.582551+00:00') ON DUPLICATE KEY UPDATE `id`=`id`;
